/** Shape-based workbook importer. Headers, not row numbers. */

import ExcelJS from "exceljs";
import { parseAvailability, parseClock, parseHumanDate, parseSeasonTitle, inferYear } from "./dates";
import {
  norm,
  splitList,
  type AgeGroup,
  type Association,
  type Campus,
  type CarveOut,
  type Child,
  type Family,
  type Field,
  type FieldType,
  type ImportIssue,
  type ImportResult,
  type League,
  type Parent,
  type PreferredSlot,
  type Season,
  type SpecialDate,
  type Staff,
  type Team,
  type TravelCell,
} from "./model";
import { requiredSheetNames, structuralRefusals, fillCrowFlies } from "./validate";

const REQUIRED = requiredSheetNames();

function cellText(cell: ExcelJS.Cell | undefined): string {
  if (!cell) return "";
  const v = cell.value;
  if (v == null) return "";
  if (typeof v === "string" || typeof v === "number" || typeof v === "boolean") return String(v).trim();
  if (v instanceof Date) {
    const y = v.getUTCFullYear();
    const m = String(v.getUTCMonth() + 1).padStart(2, "0");
    const d = String(v.getUTCDate()).padStart(2, "0");
    return `${y}-${m}-${d}`;
  }
  if (typeof v === "object") {
    const any = v as { text?: string; richText?: { text: string }[]; result?: unknown; hyperlink?: string };
    if (any.richText) return any.richText.map((t) => t.text).join("").trim();
    if (any.text) return String(any.text).trim();
    if (any.result != null) return String(any.result).trim();
    if (any.hyperlink) return String(any.hyperlink).trim();
  }
  return String(v).trim();
}

function sheetByName(wb: ExcelJS.Workbook, want: string): ExcelJS.Worksheet | undefined {
  const n = norm(want);
  return wb.worksheets.find((s) => norm(s.name) === n);
}

const HEADER_CANON: Record<string, string[]> = {
    "age group": ["age group", "age groups", "bracket", "age"],
    "game length": ["game length", "game length minutes", "minutes", "length"],
    "minimum on the field": ["minimum on the field", "min on the field", "min players", "minimum"],
    "maximum on the field": ["maximum on the field", "max on the field", "max players", "maximum"],
    "assistant referees min": ["assistant referees min", "assistants min", "assistant min", "min assistants"],
    "assistant referees preferred": ["assistant referees preferred", "assistants preferred", "preferred assistants"],
    "acceptable field classes": ["acceptable field classes", "field classes", "classes", "field class"],
    "may play with": ["may play with", "plays with"],
    field: ["field", "name", "pitch"],
    type: ["type", "field type", "class"],
    campus: ["campus", "location"],
    parking: ["parking", "lot", "parking lot"],
    available: ["available", "hours", "availability"],
    association: ["association", "league"],
    controlled: ["controlled", "we control", "ours"],
    "home campus": ["home campus", "home"],
    "first name": ["first name", "first"],
    "last name": ["last name", "last"],
    "print name": ["print name", "printed name"],
    phone: ["phone", "phone number"],
    "center of": ["center of", "centers", "center"],
    "assistant of": ["assistant of", "assistants", "lines"],
    vacation: ["vacation", "away", "days off"],
    "sample?": ["sample", "sample?", "dummy", "dummy?"],
    title: ["title", "season"],
    "playing week starts": ["playing week starts", "week starts", "week start"],
    "first playing date": ["first playing date", "first date", "starts"],
    "last playing date": ["last playing date", "last date", "ends"],
    "rematch cap": ["rematch cap", "rematch"],
    kind: ["kind", "type"],
    date: ["date", "when"],
    note: ["note", "notes"],
    bracket: ["bracket", "age group"],
    rank: ["rank", "priority"],
    day: ["day", "weekday"],
    time: ["time", "kickoff"],
    venue: ["venue", "field", "campus"],
    team: ["team", "team name"],
    "not at": ["not at", "not", "forbidden slot"],
    "must use": ["must use", "lock"],
    "every saturday": ["every saturday", "every week"],
    street: ["street", "address", "street address"],
    latitude: ["latitude", "lat"],
    longitude: ["longitude", "lng", "lon", "long"],
    "home association": ["home association", "association"],
    "from to": ["from to", "from", "campus"],
    "side name": ["side name", "guest name", "team name"],
    jersey: ["jersey", "color"],
    "games asked": ["games asked", "games requested", "games"],
    teams: ["teams", "team count"],
};

function headerAliases(h: string): string[] {
  const n = norm(h);
  for (const [canon, aliases] of Object.entries(HEADER_CANON)) {
    if (aliases.includes(n) || canon === n) return [canon, ...aliases];
  }
  return [n];
}

function bindHeaderCell(cols: Map<string, number>, header: string, col: number) {
  const n = norm(header);
  if (!n) return;
  if (!cols.has(n)) cols.set(n, col);
  for (const [canon, aliases] of Object.entries(HEADER_CANON)) {
    if (canon === n || aliases.includes(n)) {
      if (!cols.has(canon)) cols.set(canon, col);
    }
  }
}

function headersMatch(cell: string, want: string): boolean {
  const n = norm(cell);
  return headerAliases(want).includes(n) || n === norm(want);
}

function findHeaderRow(ws: ExcelJS.Worksheet, wants: string[], maxScan = 25): { row: number; cols: Map<string, number> } | null {
  const maxRow = Math.min(ws.rowCount || 0, maxScan);
  const maxCol = Math.max(ws.columnCount || 0, 20);
  for (let r = 1; r <= maxRow; r++) {
    const cols = new Map<string, number>();
    for (let c = 1; c <= maxCol; c++) {
      const t = cellText(ws.getRow(r).getCell(c));
      if (!t) continue;
      for (const want of wants) {
        if (!cols.has(want) && headersMatch(t, want)) cols.set(want, c);
      }
    }
    const hits = wants.filter((w) => cols.has(w)).length;
    if (hits >= Math.min(2, wants.length) && hits >= Math.ceil(wants.length * 0.4)) {
      for (let c = 1; c <= maxCol; c++) {
        const t = cellText(ws.getRow(r).getCell(c));
        if (t) bindHeaderCell(cols, t, c);
      }
      return { row: r, cols };
    }
  }
  return null;
}

function isBlankRow(ws: ExcelJS.Worksheet, r: number, cols: number[]): boolean {
  return cols.every((c) => !cellText(ws.getRow(r).getCell(c)));
}

function truthy(s: string): boolean {
  return /^(yes|y|true|1|sample)$/i.test(s.trim());
}

function num(s: string): number | null {
  if (!s.trim()) return null;
  const n = Number(String(s).replace(/[^\d.-]/g, ""));
  return Number.isFinite(n) ? n : null;
}

export async function parseWorkbook(data: ArrayBuffer | Uint8Array, filename = ""): Promise<ImportResult> {
  const issues: ImportIssue[] = [];
  const report: string[] = [];
  const lower = filename.toLowerCase();
  if (lower.endsWith(".csv") || lower.endsWith(".txt")) {
    return {
      ok: false,
      issues: [
        {
          level: "refuse",
          code: "not-workbook",
          message: "This is not the Van Season workbook. Download the sample and copy your data into those colored sheets.",
        },
      ],
      report,
    };
  }

  const wb = new ExcelJS.Workbook();
  try {
    await wb.xlsx.load(data as ExcelJS.Buffer);
  } catch {
    return {
      ok: false,
      issues: [
        {
          level: "refuse",
          code: "not-workbook",
          message: "This is not the Van Season workbook. Download the sample and copy your data into those colored sheets.",
        },
      ],
      report,
    };
  }

  const present = wb.worksheets.map((s) => s.name);
  const missingShapes: string[] = [];
  for (const req of REQUIRED) {
    if (!sheetByName(wb, req)) missingShapes.push(req);
  }
  if (missingShapes.length >= 4) {
    return {
      ok: false,
      issues: [
        {
          level: "refuse",
          code: "missing-shapes",
          message: `This is not the Van Season workbook. Missing shapes: ${missingShapes.join(", ")}`,
        },
      ],
      report,
    };
  }
  if (missingShapes.length) {
    return {
      ok: false,
      issues: [
        {
          level: "refuse",
          code: "missing-shapes",
          message: `The refusal card now lists the missing shapes: "${missingShapes.join(", ")}"`,
        },
      ],
      report,
    };
  }

  for (const ws of wb.worksheets) {
    const maxRow = Math.min(ws.rowCount || 0, 8);
    const maxCol = Math.max(ws.columnCount || 0, 80);
    for (let r = 1; r <= maxRow; r++) {
      for (let c = 1; c <= maxCol; c++) {
        const h = cellText(ws.getRow(r).getCell(c));
        if (/^(address|zip|zip code|home address)$/i.test(h.trim())) {
          if (!issues.some((i) => i.message === "Ignored column: Address")) {
            issues.push({ level: "warn", code: "ignored-column", message: "Ignored column: Address" });
          }
        }
      }
    }
  }

  const ageGroups = readAgeGroups(sheetByName(wb, "Age groups")!, report);
  const fieldTypes = readFieldTypes(sheetByName(wb, "Field types"));
  const fields = readFields(sheetByName(wb, "Fields")!);
  const campuses = readCampuses(sheetByName(wb, "Campuses")!);
  const associations = readAssociations(sheetByName(wb, "Associations")!);
  const travel = readTravel(sheetByName(wb, "Travel"), campuses);
  const families = readFamilies(sheetByName(wb, "Families")!);
  const staff = readStaff(sheetByName(wb, "Staff")!);
  const teams = readTeams(sheetByName(wb, "Teams")!);
  const { season, dateIssues } = readSeason(sheetByName(wb, "Season")!);
  issues.push(...dateIssues);
  const preferredSlots = readPreferred(sheetByName(wb, "Preferred slots"));
  const carveOuts = readCarveOuts(sheetByName(wb, "Carve-outs"));

  const league: League = {
    ageGroups,
    fieldTypes,
    fields,
    campuses,
    associations,
    travel,
    families,
    staff,
    teams,
    season,
    preferredSlots,
    carveOuts,
    sourceName: filename || undefined,
    sampleOnly: teams.every((t) => t.sample) && staff.every((s) => s.sample || !s.last),
  };
  league.travel = fillCrowFlies(league);

  const refusals = structuralRefusals(league);
  issues.push(...refusals);
  if (refusals.length) {
    return { ok: false, issues, report };
  }

  return { ok: true, league, issues, report };
}

function readAgeGroups(ws: ExcelJS.Worksheet, report: string[]): AgeGroup[] {
  const found = findHeaderRow(ws, [
    "age group",
    "minimum on the field",
    "maximum on the field",
    "game length",
    "assistant referees min",
    "assistant referees preferred",
    "acceptable field classes",
    "may play with",
    "sample?",
  ]);
  if (!found) return [];
  const out: AgeGroup[] = [];
  const cols = [...found.cols.values()];
  for (let r = found.row + 1; r <= (ws.rowCount || found.row); r++) {
    if (isBlankRow(ws, r, cols)) continue;
    const name = take(ws, r, found.cols, "age group");
    if (!name || headersMatch(name, "age group")) continue;
    out.push({
      name,
      minOnField: num(take(ws, r, found.cols, "minimum on the field")),
      maxOnField: num(take(ws, r, found.cols, "maximum on the field")),
      gameLengthMinutes: num(take(ws, r, found.cols, "game length")),
      assistantMin: num(take(ws, r, found.cols, "assistant referees min")),
      assistantPreferred: num(take(ws, r, found.cols, "assistant referees preferred")),
      fieldClasses: splitList(take(ws, r, found.cols, "acceptable field classes")),
      mayPlayWith: splitList(take(ws, r, found.cols, "may play with") || name),
      sample: truthy(take(ws, r, found.cols, "sample?")),
    });
  }
  report.push(`Age groups: ${out.length} blocks read${out.some((a) => a.name === "12U") ? ", including 12U" : ""}`);
  return out;
}

function take(ws: ExcelJS.Worksheet, r: number, cols: Map<string, number>, key: string): string {
  const c = cols.get(key);
  if (!c) return "";
  return cellText(ws.getRow(r).getCell(c));
}

function readFieldTypes(ws: ExcelJS.Worksheet | undefined): FieldType[] {
  if (!ws) return [];
  const found = findHeaderRow(ws, ["field type", "width", "length"]);
  if (!found) {
    // header might be "type"
    const alt = findHeaderRow(ws, ["type", "width", "length"]);
    if (!alt) return [];
    return collectFieldTypes(ws, alt);
  }
  return collectFieldTypes(ws, found);
}

function collectFieldTypes(ws: ExcelJS.Worksheet, found: { row: number; cols: Map<string, number> }): FieldType[] {
  const out: FieldType[] = [];
  const nameKey = found.cols.has("field type") ? "field type" : found.cols.has("type") ? "type" : "field type";
  if (!found.cols.has("field type") && found.cols.has("type")) found.cols.set("field type", found.cols.get("type")!);
  for (let r = found.row + 1; r <= (ws.rowCount || 0); r++) {
    const name = take(ws, r, found.cols, "field type") || take(ws, r, found.cols, nameKey);
    if (!name) continue;
    out.push({
      name,
      width: num(take(ws, r, found.cols, "width")) || 0,
      length: num(take(ws, r, found.cols, "length")) || 0,
    });
  }
  return out;
}

function readFields(ws: ExcelJS.Worksheet): Field[] {
  const found = findHeaderRow(ws, ["field", "type", "campus", "parking", "available", "sample?"]);
  if (!found) return [];
  const out: Field[] = [];
  for (let r = found.row + 1; r <= (ws.rowCount || 0); r++) {
    const name = take(ws, r, found.cols, "field");
    if (!name || headersMatch(name, "field")) continue;
    const availableRaw = take(ws, r, found.cols, "available");
    out.push({
      name,
      type: take(ws, r, found.cols, "type"),
      campus: take(ws, r, found.cols, "campus"),
      parking: take(ws, r, found.cols, "parking"),
      availableRaw,
      windows: parseAvailability(availableRaw),
      sample: truthy(take(ws, r, found.cols, "sample?")),
    });
  }
  return out;
}

function readCampuses(ws: ExcelJS.Worksheet): Campus[] {
  const found = findHeaderRow(ws, ["campus", "street", "latitude"]);
  if (!found) {
    const alt = findHeaderRow(ws, ["campus", "home association"]);
    if (!alt) return [];
    return collectCampuses(ws, alt);
  }
  return collectCampuses(ws, found);
}

function collectCampuses(ws: ExcelJS.Worksheet, found: { row: number; cols: Map<string, number> }): Campus[] {
  const out: Campus[] = [];
  for (let r = found.row + 1; r <= (ws.rowCount || 0); r++) {
    const name = take(ws, r, found.cols, "campus");
    if (!name || /guest sides/i.test(name)) break;
    const lat = num(take(ws, r, found.cols, "latitude"));
    const lng = num(take(ws, r, found.cols, "longitude"));
    out.push({
      name,
      association: take(ws, r, found.cols, "home association"),
      street: take(ws, r, found.cols, "street"),
      lat: lat ?? undefined,
      lng: lng ?? undefined,
    });
  }
  return out;
}

function readAssociations(ws: ExcelJS.Worksheet): Association[] {
  const found = findHeaderRow(ws, ["association", "controlled"]);
  const map = new Map<string, Association>();
  if (found) {
    for (let r = found.row + 1; r <= (ws.rowCount || 0); r++) {
      const name = take(ws, r, found.cols, "association");
      if (!name || /guest/i.test(name)) break;
      if (headersMatch(name, "association")) break;
      const controlled = truthy(take(ws, r, found.cols, "controlled"));
      map.set(name, {
        name,
        controlled,
        homeCampus: take(ws, r, found.cols, "home campus"),
        guestSides: [],
      });
    }
  }
  // guest sides table
  const guest = findHeaderRow(ws, ["association", "age group", "teams", "games asked"]);
  if (guest) {
    for (let r = guest.row + 1; r <= (ws.rowCount || 0); r++) {
      const name = take(ws, r, guest.cols, "association");
      const ag = take(ws, r, guest.cols, "age group");
      if (!name || !ag) continue;
      const rec = map.get(name) || { name, controlled: false, guestSides: [] };
      rec.guestSides.push({
        ageGroup: ag,
        teamCount: num(take(ws, r, guest.cols, "teams")) || 0,
        gamesRequested: num(take(ws, r, guest.cols, "games asked")) || 0,
        name: take(ws, r, guest.cols, "side name") || undefined,
        jersey: take(ws, r, guest.cols, "jersey") || undefined,
      });
      map.set(name, rec);
    }
  }
  return [...map.values()];
}

function readTravel(ws: ExcelJS.Worksheet | undefined, campuses: Campus[]): TravelCell[] {
  const cells: TravelCell[] = [];
  if (!ws) return cells;
  // matrix: first row campuses, first col campuses
  const headerRow = 1;
  const names: string[] = [];
  const maxCol = Math.max(ws.columnCount || 0, 12);
  for (let c = 2; c <= maxCol; c++) {
    const t = cellText(ws.getRow(headerRow).getCell(c));
    if (t) names.push(t);
  }
  if (names.length >= 2) {
    for (let r = 2; r <= names.length + 4; r++) {
      const from = cellText(ws.getRow(r).getCell(1));
      if (!from) continue;
      for (let i = 0; i < names.length; i++) {
        const raw = cellText(ws.getRow(r).getCell(i + 2));
        const minutes = num(raw);
        if (minutes == null) continue;
        cells.push({ from, to: names[i], minutes });
      }
    }
    return cells;
  }
  void campuses;
  return cells;
}

function readFamilies(ws: ExcelJS.Worksheet): Family[] {
  const found = findHeaderRow(ws, ["parent 1 first name", "parent 1 last name", "parent 1 phone"]);
  if (!found) {
    // looser: first name columns
    return readFamiliesLoose(ws);
  }
  const out: Family[] = [];
  const maxCol = Math.max(ws.columnCount || 0, 60);
  // also collect kid columns by scanning header
  const header = ws.getRow(found.row);
  const kidCols: { n: number; first?: number; last?: number; bracket?: number; team?: number; jersey?: number }[] = [];
  for (let c = 1; c <= maxCol; c++) {
    const h = cellText(header.getCell(c));
    const m = h.match(/^kid\s*(\d+)\s*(.*)$/i);
    if (!m) continue;
    const n = Number(m[1]);
    let slot = kidCols.find((k) => k.n === n);
    if (!slot) {
      slot = { n };
      kidCols.push(slot);
    }
    const rest = norm(m[2]);
    if (!rest || rest === "first name" || rest === "first" || rest === "name") slot.first = c;
    else if (rest === "last name" || rest === "last") slot.last = c;
    else if (rest === "bracket" || rest === "age group") slot.bracket = c;
    else if (rest === "team") slot.team = c;
    else if (rest === "jersey") slot.jersey = c;
  }
  kidCols.sort((a, b) => a.n - b.n);

  const colNamed = (re: RegExp): number | undefined => {
    for (let c = 1; c <= maxCol; c++) {
      if (re.test(norm(cellText(header.getCell(c))))) return c;
    }
    return undefined;
  };

  for (let r = found.row + 1; r <= (ws.rowCount || 0); r++) {
    const p1f = take(ws, r, found.cols, "parent 1 first name") || cellText(ws.getRow(r).getCell(colNamed(/parent 1 first/) || 0));
    const p1l = take(ws, r, found.cols, "parent 1 last name");
    if (!p1f && !p1l) continue;
    const parents: Parent[] = [];
    const mk = (prefix: string): Parent | null => {
      const first = pick(ws, r, header, new RegExp(`^${prefix} first`));
      const last = pick(ws, r, header, new RegExp(`^${prefix} last`));
      if (!first && !last) return null;
      return {
        first,
        last,
        printName: pick(ws, r, header, new RegExp(`^${prefix} print`)) || undefined,
        phone: pick(ws, r, header, new RegExp(`^${prefix} phone`)) || undefined,
        coachOf: splitList(pick(ws, r, header, new RegExp(`^${prefix} coach`))),
        assistantOf: splitList(pick(ws, r, header, new RegExp(`^${prefix} assistant`))),
      };
    };
    const a = mk("parent 1");
    const b = mk("parent 2");
    if (a) parents.push(a);
    if (b) parents.push(b);
    const children: Child[] = [];
    for (const k of kidCols) {
      const first = k.first ? cellText(ws.getRow(r).getCell(k.first)) : "";
      const last = k.last ? cellText(ws.getRow(r).getCell(k.last)) : "";
      if (!first && !last) continue;
      children.push({
        first,
        last,
        bracket: k.bracket ? cellText(ws.getRow(r).getCell(k.bracket)) : "",
        team: k.team ? cellText(ws.getRow(r).getCell(k.team)) : "",
        jersey: k.jersey ? cellText(ws.getRow(r).getCell(k.jersey)) : undefined,
      });
    }
    out.push({
      code: pick(ws, r, header, /^family code$/) || undefined,
      parents,
      children,
      vacation: pick(ws, r, header, /^vacation$/) || undefined,
      sample: truthy(pick(ws, r, header, /^sample/)),
    });
  }
  return out;
}

function pick(ws: ExcelJS.Worksheet, r: number, header: ExcelJS.Row, re: RegExp): string {
  const maxCol = Math.max(ws.columnCount || 0, 60);
  for (let c = 1; c <= maxCol; c++) {
    if (re.test(norm(cellText(header.getCell(c))))) return cellText(ws.getRow(r).getCell(c));
  }
  return "";
}

function readFamiliesLoose(ws: ExcelJS.Worksheet): Family[] {
  const found = findHeaderRow(ws, ["first name", "last name"]);
  if (!found) return [];
  const out: Family[] = [];
  for (let r = found.row + 1; r <= (ws.rowCount || 0); r++) {
    const first = take(ws, r, found.cols, "first name");
    const last = take(ws, r, found.cols, "last name");
    if (!first && !last) continue;
    out.push({
      parents: [{ first, last, phone: take(ws, r, found.cols, "phone"), coachOf: [], assistantOf: [] }],
      children: [],
      sample: truthy(take(ws, r, found.cols, "sample?")),
    });
  }
  return out;
}

function readStaff(ws: ExcelJS.Worksheet): Staff[] {
  const found = findHeaderRow(ws, [
    "first name",
    "last name",
    "print name",
    "phone",
    "center of",
    "assistant of",
    "vacation",
    "sample?",
  ]);
  if (!found) return [];
  const out: Staff[] = [];
  for (let r = found.row + 1; r <= (ws.rowCount || 0); r++) {
    const first = take(ws, r, found.cols, "first name");
    const last = take(ws, r, found.cols, "last name");
    if (!first && !last) continue;
    out.push({
      first,
      last,
      printName: take(ws, r, found.cols, "print name") || undefined,
      phone: take(ws, r, found.cols, "phone") || undefined,
      centerOf: splitList(take(ws, r, found.cols, "center of")),
      assistantOf: splitList(take(ws, r, found.cols, "assistant of")),
      vacation: take(ws, r, found.cols, "vacation") || undefined,
      sample: truthy(take(ws, r, found.cols, "sample?")),
    });
  }
  return out;
}

function readTeams(ws: ExcelJS.Worksheet): Team[] {
  const teams: Team[] = [];
  const maxRow = ws.rowCount || 0;
  let current: Team | null = null;
  const flush = () => {
    if (current && current.name) teams.push(current);
    current = null;
  };
  for (let r = 1; r <= maxRow; r++) {
    const label = cellText(ws.getRow(r).getCell(1));
    const value = cellText(ws.getRow(r).getCell(2));
    const n = norm(label);
    if (!n) {
      if (current && current.name) {
        // blank row ends a block when we already have a name
        const nextLabel = cellText(ws.getRow(r + 1).getCell(1));
        if (!nextLabel || norm(nextLabel) === "team name") flush();
      }
      continue;
    }
    if (n === "team name") {
      flush();
      current = {
        name: value,
        bracket: "",
        association: "",
        jersey: "",
        players: [],
        willNotPlay: [],
        willNotTravelTo: [],
        awayDesired: 0,
        guestDesired: 0,
      };
      continue;
    }
    if (!current) continue;
    if (n === "bracket") current.bracket = value;
    else if (n === "association") current.association = value;
    else if (n === "jersey") current.jersey = value;
    else if (n === "coach first") current.coach = { ...(current.coach || { first: "", last: "" }), first: value };
    else if (n === "coach last") current.coach = { ...(current.coach || { first: "", last: "" }), last: value };
    else if (n === "coach phone") current.coach = { ...(current.coach || { first: "", last: "" }), phone: value };
    else if (n === "assistant first") current.assistant = { ...(current.assistant || { first: "", last: "" }), first: value };
    else if (n === "assistant last") current.assistant = { ...(current.assistant || { first: "", last: "" }), last: value };
    else if (n === "assistant phone") current.assistant = { ...(current.assistant || { first: "", last: "" }), phone: value };
    else if (n === "will not play") current.willNotPlay = splitList(value);
    else if (n === "will not travel to") current.willNotTravelTo = splitList(value);
    else if (n === "away games desired") current.awayDesired = num(value) || 0;
    else if (n === "guest games desired") current.guestDesired = num(value) || 0;
    else if (n === "guest travel") current.guestTravel = value || undefined;
    else if (n === "minimum on the field") current.minOnField = num(value) ?? undefined;
    else if (n === "sample" || n === "sample?") current.sample = truthy(value);
    else if (/^kid \d+$/.test(n) && value) current.players.push({ name: value });
    else if (/^kid \d+ jersey$/.test(n) && value && current.players.length) {
      current.players[current.players.length - 1].jersey = value;
    }
  }
  flush();
  return teams;
}

function readSeason(ws: ExcelJS.Worksheet): { season: Season; dateIssues: ImportIssue[] } {
  const dateIssues: ImportIssue[] = [];
  const kv = new Map<string, string>();
  const maxRow = ws.rowCount || 0;
  for (let r = 1; r <= maxRow; r++) {
    const k = cellText(ws.getRow(r).getCell(1));
    const v = cellText(ws.getRow(r).getCell(2));
    if (k && v && !/^(field|kind)$/i.test(k)) kv.set(norm(k), v);
  }
  const title = kv.get("title") || kv.get("season") || "Fall 2026 to 2027";
  const year = inferYear(title, 2026);
  const firstRaw = kv.get("first playing date") || "";
  const lastRaw = kv.get("last playing date") || "";
  const firstIso = parseHumanDate(firstRaw, year) || undefined;
  const lastIso = parseHumanDate(lastRaw, year) || undefined;
  const associationName = kv.get("association") || "Van Season";
  const headerTitle = parseSeasonTitle(title) || title;

  const specials: SpecialDate[] = [];
  const kindRow = findHeaderRow(ws, ["kind", "date"]);
  if (kindRow) {
    for (let r = kindRow.row + 1; r <= maxRow; r++) {
      const kindRaw = take(ws, r, kindRow.cols, "kind");
      const dateRaw = take(ws, r, kindRow.cols, "date");
      const note = take(ws, r, kindRow.cols, "note");
      if (!kindRaw && !dateRaw) continue;
      const blob = `${kindRaw} ${dateRaw} ${note}`;
      let kind: SpecialDate["kind"] = "bye";
      if (/rain/i.test(blob)) kind = "rain-check";
      else if (/interleague/i.test(blob) && /away/i.test(blob)) kind = "interleague-away";
      else if (/interleague/i.test(blob) || /guest/i.test(blob)) kind = "interleague-home";
      else if (/bye|thanksgiving|no games/i.test(blob)) kind = "bye";
      const iso = parseHumanDate(dateRaw, year) || parseHumanDate(blob, year) || undefined;
      if (dateRaw && !iso && /satuday|fifthish|ish\b/i.test(dateRaw)) {
        dateIssues.push({
          level: "warn",
          code: "unreadable-date",
          message: `Could not read this date. Write it like Sunday, November 8 or 2026-11-08.`,
        });
        specials.push({ kind, raw: dateRaw, unreadable: dateRaw, note });
        continue;
      }
      specials.push({ kind, raw: dateRaw || kindRaw, iso, note });
    }
  }
  // key-value bye line without table
  for (const [k, v] of kv) {
    if (k.includes("bye") || /thanksgiving/i.test(v)) {
      if (!specials.some((s) => s.kind === "bye")) {
        const iso = parseHumanDate(v, year);
        specials.push({ kind: "bye", raw: v, iso: iso || undefined, note: v });
      }
    }
  }

  const season: Season = {
    associationName,
    title,
    headerTitle,
    weekStarts: kv.get("playing week starts") || "Saturday",
    firstRaw,
    lastRaw,
    firstIso,
    lastIso,
    rematchCap: num(kv.get("rematch cap") || "2") || 2,
    specials,
    dateFlags: dateIssues.map((i) => ({ raw: i.message, message: i.message })),
  };
  return { season, dateIssues };
}

function readPreferred(ws: ExcelJS.Worksheet | undefined): PreferredSlot[] {
  if (!ws) return [];
  const found = findHeaderRow(ws, ["bracket", "rank", "day", "time"]);
  if (!found) return [];
  const out: PreferredSlot[] = [];
  for (let r = found.row + 1; r <= (ws.rowCount || 0); r++) {
    const bracket = take(ws, r, found.cols, "bracket");
    if (!bracket) continue;
    out.push({
      bracket,
      rank: num(take(ws, r, found.cols, "rank")) || 0,
      day: take(ws, r, found.cols, "day"),
      time: take(ws, r, found.cols, "time"),
      venue: take(ws, r, found.cols, "venue") || undefined,
    });
  }
  return out;
}

function readCarveOuts(ws: ExcelJS.Worksheet | undefined): CarveOut[] {
  if (!ws) return [];
  const found = findHeaderRow(ws, ["team", "date"]);
  if (!found) return [];
  const out: CarveOut[] = [];
  for (let r = found.row + 1; r <= (ws.rowCount || 0); r++) {
    const team = take(ws, r, found.cols, "team");
    if (!team) continue;
    out.push({
      team,
      date: take(ws, r, found.cols, "date") || undefined,
      notAt: take(ws, r, found.cols, "not at") || undefined,
      mustUse: take(ws, r, found.cols, "must use") || undefined,
      everySaturday: truthy(take(ws, r, found.cols, "every saturday")),
    });
  }
  return out;
}

