/** Compact Tabulator schedule: one sheet per bracket, pointer-drag to swap slots. */

import { TabulatorFull as Tabulator } from "tabulator-tables";
import "tabulator-tables/dist/css/tabulator_simple.min.css";
import { formatSheetDate, formatSheetTime, parseClock } from "./dates";
import type { Configuration, League, PlacedGame } from "./model";
import { publishedClubName } from "./publish";
import { seasonBurnLines } from "./sims";
import { campusStreet } from "./validate";

const SLOT = [
  "dateIso",
  "weekIso",
  "kickoff",
  "end",
  "warmupStart",
  "vacate",
  "field",
  "campus",
  "parking",
] as const;

export function swapGameSlots(a: PlacedGame, b: PlacedGame): void {
  for (const k of SLOT) {
    const tmp = a[k];
    Object.assign(a, { [k]: b[k] });
    Object.assign(b, { [k]: tmp });
  }
}

export interface ScoreSnap {
  z3: number | undefined;
  diversity: number | undefined;
  simsLegal: boolean;
  burns: string[];
}

export function scoreSnap(league: League, cfg: Configuration): ScoreSnap {
  return {
    z3: cfg.z3Season?.score,
    diversity: cfg.diversity?.score,
    simsLegal: cfg.simsValid !== false && !cfg.scores.some((s) => s.key === "sims" && /not legal/i.test(s.text)),
    burns: seasonBurnLines(league, cfg),
  };
}

function deltaWord(before: number | undefined, after: number | undefined, higherIsBetter: boolean): "better" | "worse" | "same" {
  if (before == null || after == null || before === after) return "same";
  const up = after > before;
  return (higherIsBetter ? up : !up) ? "better" : "worse";
}

export function ramificationCopy(
  swapLine: string,
  before: ScoreSnap,
  after: ScoreSnap,
): { html: string; kind: "better" | "worse" | "same" } {
  const z = deltaWord(before.z3, after.z3, true);
  const d = deltaWord(before.diversity, after.diversity, true);
  const s: "better" | "worse" | "same" =
    before.simsLegal === after.simsLegal ? "same" : after.simsLegal ? "better" : "worse";
  const kind = [z, d, s].includes("worse") ? "worse" : [z, d, s].includes("better") ? "better" : "same";
  const newBurns = after.burns.filter((b) => !before.burns.includes(b));
  const html = `<p data-ramification-swap>${swapLine}</p>
    <p data-ramification-z3 data-delta="${z}">Z3 season ${before.z3 ?? "—"} → ${after.z3 ?? "—"} (${z})</p>
    <p data-ramification-diversity data-delta="${d}">Diversity ${before.diversity ?? "—"} → ${after.diversity ?? "—"} (${d})</p>
    <p data-ramification-sims data-delta="${s}">Sims ${before.simsLegal ? "legal" : "not legal"} → ${after.simsLegal ? "legal" : "not legal"} (${s})</p>
    ${newBurns.length ? newBurns.map((b) => `<p class="flag" data-ramification-burn>${b}</p>`).join("") : `<p class="meta" data-ramification-burn="none">No new household or whistle burns.</p>`}`;
  return { html, kind };
}

export function isDateLead(dateIso: string, prevDateIso?: string | null): boolean {
  return !prevDateIso || prevDateIso !== dateIso;
}

export function dropTargetId(pulledId: string | null | undefined, underId: string | null | undefined): string | undefined {
  if (!pulledId || !underId || pulledId === underId) return undefined;
  return underId;
}

export function isAwayCampus(location: string): boolean {
  return !/van/i.test(location || "");
}

/** Terse campus for the sheet — never a street. Packets still print the address. */
export function terseCampus(campus: string): string {
  if (!campus || /^tba$/i.test(campus)) return "TBA";
  if (/van/i.test(campus)) return /stadium|high school/i.test(campus) ? "Van Stadium" : "Van";
  return campus.replace(/\s+Complex$/i, "").replace(/\s+High School.*$/i, "").trim() || "TBA";
}

/** LOCATION column: campus plus grass. Streets live on title / data-street. */
export function sheetLocation(_league: League, campus: string, field: string): string {
  const loc = terseCampus(campus);
  let f = (field || "").replace(/^Field\s+/i, "").trim();
  if (f && loc && f.toLowerCase().startsWith(loc.toLowerCase())) {
    f = f.slice(loc.length).replace(/^[\s·\-]+/, "").trim();
  }
  if (f && /stadium/i.test(loc) && /stadium/i.test(f)) return loc;
  return f ? `${loc} · ${f}` : loc;
}

export function sheetClubName(league: League, label: string, bracket: string): string {
  const full = publishedClubName(league, label);
  if (!bracket) return full;
  const cut = full.split(bracket).join("").replace(/\s+/g, " ").trim();
  return cut || full;
}

/** First Saturday with 2+ games in the bracket, else the whole season. */
export function kickoffMinutes(raw: string): number {
  const n = parseClock(raw);
  if (n == null) return 24 * 60;
  return n < 7 * 60 ? n + 12 * 60 : n;
}

export function compareSheetGames(
  a: { dateIso: string; kickoff: string; field: string },
  b: { dateIso: string; kickoff: string; field: string },
): number {
  return a.dateIso.localeCompare(b.dateIso) || kickoffMinutes(a.kickoff) - kickoffMinutes(b.kickoff) || a.field.localeCompare(b.field);
}

export function weekForBracket(
  games: PlacedGame[],
  bracket: string,
  requested?: string | null,
): string | undefined {
  const of = games.filter((g) => g.ageGroup === bracket);
  if (requested === "all") return undefined;
  if (requested && of.some((g) => g.dateIso === requested)) return requested;
  const dates = [...new Set(of.map((g) => g.dateIso))].sort();
  const first = dates[0];
  if (first && of.filter((g) => g.dateIso === first).length >= 2) return first;
  return undefined;
}

type Row = {
  id: string;
  dateIso: string;
  date: string;
  time: string;
  home: string;
  away: string;
  location: string;
  street: string;
  bracket: string;
  homeLabel: string;
  awayLabel: string;
};

function rowsFor(league: League, games: PlacedGame[], bracket: string, weekIso?: string): Row[] {
  return games
    .filter((g) => g.ageGroup === bracket && (!weekIso || g.dateIso === weekIso))
    .sort(compareSheetGames)
    .map((g) => ({
      id: g.id,
      dateIso: g.dateIso,
      date: formatSheetDate(g.dateIso),
      time: formatSheetTime(g.kickoff),
      home: sheetClubName(league, g.home, bracket),
      away: sheetClubName(league, g.away, bracket),
      location: sheetLocation(league, g.campus, g.field),
      street: campusStreet(league, g.campus) || "",
      bracket: g.ageGroup,
      homeLabel: g.home,
      awayLabel: g.away,
    }));
}

function rowEl(from: EventTarget | null): HTMLElement | null {
  return (from as HTMLElement | null)?.closest?.(".tabulator-row[data-game]") ?? null;
}

let table: { destroy: () => void; getData: () => Row[] } | null = null;
let drag: {
  pulledId: string;
  pointerId: number;
  ghost: HTMLElement;
  host: HTMLElement;
  onDrop: (pulledId: string, targetId: string) => void;
} | null = null;

function onDragKey(e: KeyboardEvent): void {
  if (e.key === "Escape") abortDrag();
}

function abortDrag(): void {
  if (!drag) return;
  document.removeEventListener("keydown", onDragKey);
  drag.ghost.remove();
  drag.host.classList.remove("sheet-dragging");
  drag.host.removeAttribute("data-sheet-dragging");
  drag.host.querySelectorAll(".sheet-drop-target, .sheet-row-lifted").forEach((el) => {
    el.classList.remove("sheet-drop-target", "sheet-row-lifted");
  });
  try {
    drag.host.releasePointerCapture(drag.pointerId);
  } catch {
    /* already released */
  }
  drag = null;
}

function moveGhost(e: PointerEvent): void {
  if (!drag) return;
  drag.ghost.style.left = `${e.clientX + 12}px`;
  drag.ghost.style.top = `${e.clientY - 10}px`;
}

function paintDropTarget(host: HTMLElement, underId: string | undefined): void {
  host.querySelectorAll(".sheet-drop-target").forEach((el) => el.classList.remove("sheet-drop-target"));
  if (!underId) return;
  host.querySelector(`[data-game="${underId}"]`)?.classList.add("sheet-drop-target");
}

function bindPointerSwap(host: HTMLElement, onDrop: (pulledId: string, targetId: string) => void): void {
  host.addEventListener("pointerdown", (e) => {
    if (e.button !== 0) return;
    const row = rowEl(e.target);
    if (!row) return;
    const pulledId = row.getAttribute("data-game");
    if (!pulledId) return;
    e.preventDefault();
    abortDrag();
    row.classList.add("sheet-row-lifted");
    const ghost = row.cloneNode(true) as HTMLElement;
    ghost.removeAttribute("data-game");
    ghost.setAttribute("data-sheet-ghost", "yes");
    ghost.classList.add("sheet-ghost");
    ghost.style.width = `${row.getBoundingClientRect().width}px`;
    document.body.appendChild(ghost);
    host.classList.add("sheet-dragging");
    host.setAttribute("data-sheet-dragging", "yes");
    document.addEventListener("keydown", onDragKey);
    drag = { pulledId, pointerId: e.pointerId, ghost, host, onDrop };
    try {
      host.setPointerCapture(e.pointerId);
    } catch {
      /* headless still delivers move/up */
    }
    moveGhost(e);
  });
  host.addEventListener("pointermove", (e) => {
    if (!drag || drag.host !== host) return;
    moveGhost(e);
    const under = rowEl(document.elementFromPoint(e.clientX, e.clientY));
    const targetId = dropTargetId(drag.pulledId, under?.getAttribute("data-game"));
    paintDropTarget(host, targetId);
  });
  const finish = (e: PointerEvent) => {
    if (!drag || drag.host !== host) return;
    const under = rowEl(document.elementFromPoint(e.clientX, e.clientY));
    const targetId = dropTargetId(drag.pulledId, under?.getAttribute("data-game"));
    const pulledId = drag.pulledId;
    const drop = drag.onDrop;
    abortDrag();
    if (targetId) drop(pulledId, targetId);
  };
  host.addEventListener("pointerup", finish);
  host.addEventListener("pointercancel", () => {
    if (drag?.host === host) abortDrag();
  });
}

export function destroyScheduleSheet(): void {
  abortDrag();
  table?.destroy();
  table = null;
}

export function mountScheduleSheet(
  host: HTMLElement,
  league: League,
  cfg: Configuration,
  bracket: string,
  onSwap: (pulled: PlacedGame, target: PlacedGame) => void,
  weekIso?: string,
): void {
  destroyScheduleSheet();
  const data = rowsFor(league, cfg.games, bracket, weekIso);
  const groupSaturdays = !weekIso && data.some((r) => data.filter((x) => x.dateIso === r.dateIso).length >= 2);
  const compact = data.length <= 10;
  host.setAttribute("data-sheet-ready", "no");
  host.setAttribute("data-sheet-compact", compact ? "yes" : "no");
  const grid = new Tabulator(host, {
    data,
    layout: "fitColumns",
    ...(compact ? { maxHeight: "100%" } : { height: "100%" }),
    movableRows: false,
    reactiveData: false,
    headerSort: false,
    renderHorizontal: "basic",
    placeholder: "No games in this bracket.",
    ...(groupSaturdays
      ? {
          groupBy: "dateIso",
          groupStartOpen: true,
          groupHeader: (value: string, count: number) =>
            `<span data-date-group="${value}">${formatSheetDate(value)} · ${count} games</span>`,
        }
      : {}),
    rowFormatter: (row: { getData: () => Row; getElement: () => HTMLElement }) => {
      const d = row.getData();
      const el = row.getElement();
      el.setAttribute("data-game", d.id);
      el.setAttribute("data-week", d.dateIso);
      el.setAttribute("data-bracket", d.bracket);
      el.setAttribute("data-home", d.homeLabel);
      el.setAttribute("data-away", d.awayLabel);
      el.setAttribute("data-location", d.location);
      el.setAttribute("data-away-campus", isAwayCampus(d.location) ? "yes" : "no");
      el.setAttribute("data-time", d.time);
      if (d.street) el.setAttribute("data-street", d.street);
    },
    columns: [
      {
        title: "",
        field: "grip",
        width: 22,
        minWidth: 22,
        hozAlign: "center",
        headerSort: false,
        cssClass: "sheet-grip",
        formatter: () => {
          const span = document.createElement("span");
          span.setAttribute("data-grip", "true");
          span.setAttribute("aria-hidden", "true");
          span.textContent = "⠿";
          return span;
        },
      },
      {
        title: "DATE",
        field: "date",
        width: 72,
        hozAlign: "left",
        formatter: (cell: {
          getValue: () => string;
          getElement: () => HTMLElement;
          getRow: () => { getData: () => Row; getPrevRow: () => { getData: () => Row } | false };
        }) => {
          const prev = cell.getRow().getPrevRow();
          const show = isDateLead(cell.getRow().getData().dateIso, prev ? prev.getData().dateIso : "");
          cell.getElement().classList.toggle("sheet-date-repeat", !show);
          cell.getElement().setAttribute("data-date-lead", show ? "yes" : "no");
          return cell.getValue();
        },
      },
      { title: "TIME", field: "time", width: 78, cssClass: "sheet-time" },
      { title: "HOME", field: "home", minWidth: 140 },
      { title: "AWAY", field: "away", minWidth: 140 },
      {
        title: "LOCATION",
        field: "location",
        minWidth: 120,
        formatter: (cell: {
          getValue: () => string;
          getElement: () => HTMLElement;
          getRow: () => { getData: () => Row };
        }) => {
          const loc = cell.getValue();
          const street = cell.getRow().getData().street;
          if (isAwayCampus(loc)) cell.getElement().setAttribute("data-away-campus", "yes");
          if (street) {
            cell.getElement().setAttribute("title", street);
            cell.getElement().setAttribute("data-street", street);
          }
          return loc;
        },
      },
    ],
  });
  table = grid;
  bindPointerSwap(host, (pulledId, targetId) => {
    const pulled = cfg.games.find((g) => g.id === pulledId);
    const target = cfg.games.find((g) => g.id === targetId);
    if (!pulled || !target) return;
    onSwap(pulled, target);
  });
  const markReady = () => host.setAttribute("data-sheet-ready", "yes");
  grid.on("tableBuilt", markReady);
  queueMicrotask(() => {
    if (host.querySelector("[data-game]")) markReady();
  });
}
