const $ = <T extends HTMLElement>(sel: string) => document.querySelector(sel) as T;

const state: SeasonState & {
  misses: number;
  inspect: string;
  person?: string;
  ownScars: boolean;
  selectedId?: string;
  refreshLine?: string;
  constraintKey?: string;
  washFrom?: string;
  washNote?: string;
  sheetBracket?: string;
  sheetWeek?: string;
  ramification?: string;
  ramificationKind?: "worse" | "better" | "same";
  swapUndo?: { a: string; b: string };
} = {
  league: null,
  configurations: [],
  misses: 0,
  inspect: "teams",
  ownScars: false,
};

function selectedCfg(): Configuration | undefined {
  return state.configurations.find((c) => c.id === state.selectedId) || state.configurations[0];
}

function ensureCfg(): Configuration | undefined {
  const existing = selectedCfg();
  if (existing) return existing;
  if (!state.league) return undefined;
  const cfg: Configuration = {
    id: "cfg-1",
    name: "Configuration 1 — First pass — no carve-outs",
    createdAt: "just now",
    games: [],
    scores: [],
    hardHeld: true,
    diagnostics: [],
    engine: "z3",
    z3Verdict: "sat",
    z3Probe: "sat",
  };
  state.configurations = [cfg];
  state.selectedId = cfg.id;
  return cfg;
}

void buildVanLeague; // kept for tests / later sittings

function show(el: HTMLElement | null, on: boolean) {
  if (el) el.hidden = !on;
}

function unlock() {
  show($('[data-screen="gate"]'), false);
  show($('[data-screen="workbench"]'), true);
  render();
}

function lockMessage(ok: boolean) {
  const field = $('[data-field="password"]') as HTMLInputElement;
  const err = $('[data-error="password"]');
  const hint = $('[data-hint="audience"]');
  if (ok) {
    err.textContent = "";
    show(hint, false);
    return;
  }
  state.misses += 1;
  field.classList.remove("shake");
  void field.offsetWidth;
  field.classList.add("shake");
  err.textContent = "That password does not open Van Season.";
  if (state.misses >= 3) show(hint, true);
}

