$('[data-input="season"]').addEventListener("change", async (e) => {
  const file = (e.target as HTMLInputElement).files?.[0];
  (e.target as HTMLInputElement).value = "";
  if (!file) return;
  const buf = new Uint8Array(await file.arrayBuffer());
  const loaded = await loadSeasonFile(buf);
  state.league = loaded.league;
  state.configurations = loaded.configurations;
  state.publishedId = loaded.publishedId;
  state.selectedId = loaded.publishedId || loaded.configurations[0]?.id;
  if (state.league) {
    state.constraintKey = constraintKey(state.league);
    for (const cfg of state.configurations) restamp(cfg);
  }
  hideRefusal();
  render();
});

