$('[data-action="calculate"]').addEventListener("click", async () => {
  if (!state.league) return;
  const stopVeil = startThinkingVeil(state.league);
  await new Promise((r) => setTimeout(r, 80));
  try {
    const n = state.configurations.length + 1;
    const name =
      n === 1 && !state.league.carveOuts.length
        ? "Configuration 1 — First pass — no carve-outs"
        : `Configuration ${n} — just now`;
    const prev = selectedCfg();
    const cfg = await solveInBrowser(state.league, name);
    if (cfg.engine !== "z3" || cfg.z3Probe !== "sat") {
      throw new Error("Calculate did not run real Z3 — refusing to keep a placer result");
    }
    if (prev?.games.length) cfg.scores.push(...carveDisplacement(state.league, prev.games, cfg.games));
    cfg.id = `cfg-${n}`;
    state.configurations = [cfg, ...state.configurations];
    state.selectedId = cfg.id;
    state.constraintKey = constraintKey(state.league);
    state.refreshLine = undefined;
    state.inspect = "schedule";
    state.ownScars = false;
    stopVeil();
    render();
  } catch (err) {
    stopVeil();
    const msg = err instanceof Error ? err.message : String(err);
    showRefusal(msg);
  }
});

$("[data-config-chip]").addEventListener("click", (e) => {
  const discard = (e.target as HTMLElement).closest("[data-action='discard-config']") as HTMLElement | null;
  if (discard) {
    const id = selectedCfg()?.id;
    state.configurations = state.configurations.filter((c) => c.id !== id);
    if (state.publishedId === id) state.publishedId = undefined;
    state.selectedId = state.configurations[0]?.id;
    render();
    return;
  }
  const btn = (e.target as HTMLElement).closest("[data-config]") as HTMLElement | null;
  if (!btn) return;
  state.selectedId = btn.getAttribute("data-config") || state.selectedId;
  render();
});

