$('[data-panel="inspect-cards"]').addEventListener("click", (e) => {
  if ((e.target as HTMLElement).closest("[data-action='wash-out']")) return;
  const tab = (e.target as HTMLElement).closest("[data-sheet-tab]") as HTMLElement | null;
  if (tab) {
    state.sheetBracket = tab.getAttribute("data-sheet-tab") || undefined;
    render();
    return;
  }
  const weekBtn = (e.target as HTMLElement).closest("button[data-sheet-week]") as HTMLElement | null;
  if (weekBtn) {
    state.sheetWeek = weekBtn.getAttribute("data-sheet-week") || "all";
    render();
    return;
  }
  const link = (e.target as HTMLElement).closest("[data-link]") as HTMLElement | null;
  if (!link) return;
  const dest = link.getAttribute("data-link") || "";
  if (dest.startsWith("person:")) {
    const phone = link.getAttribute("data-phone");
    const name = dest.slice(7);
    state.person = phone ? `${name}::${phone}` : name;
    state.inspect = "person";
  } else if (dest.startsWith("team:")) {
    state.person = dest.slice(5);
    state.inspect = "team";
  } else if (dest.startsWith("field:")) {
    state.person = dest.slice(6);
    state.inspect = "field";
  } else if (dest.startsWith("campus:")) {
    state.person = dest.slice(7);
    state.inspect = "campus";
  } else if (dest.startsWith("family:")) {
    state.person = dest.slice(7);
    state.inspect = "family";
  } else if (dest === "travel") {
    state.inspect = "travel";
    state.person = undefined;
  }
  render();
});

$('[data-field="search"]').addEventListener("input", () => render());

$('[data-panel="inspect-cards"]').addEventListener("click", async (e) => {
  const target = (e.target as HTMLElement).closest("[data-doc], [data-action], [data-cast]") as HTMLElement | null;
  if (!target) return;
  if (!state.league) return;
  if (target.getAttribute("data-action") === "undo-swap") {
    const cfg = selectedCfg();
    const ids = state.swapUndo;
    if (!cfg || !state.league || !ids) return;
    const ga = cfg.games.find((g) => g.id === ids.a);
    const gb = cfg.games.find((g) => g.id === ids.b);
    if (!ga || !gb) return;
    const before = scoreSnap(state.league, cfg);
    swapGameSlots(ga, gb);
    restamp(cfg);
    const after = scoreSnap(state.league, cfg);
    const r = ramificationCopy("Undid the last swap.", before, after);
    state.ramification = r.html;
    state.ramificationKind = r.kind;
    state.swapUndo = { a: ids.b, b: ids.a };
    render();
    return;
  }
  if (target.getAttribute("data-action") === "wash-out") {
    const week = target.getAttribute("data-week") || "";
    const blocked = week && state.league ? canWashDate(state.league, week) : "No date.";
    if (blocked) {
      state.washNote = blocked;
      render();
      return;
    }
    state.washFrom = week;
    state.washNote = undefined;
    render();
    return;
  }
  if (target.getAttribute("data-action") === "rain-choice") {
    const toIso = target.getAttribute("data-rain-choice") || "";
    const fromIso = state.washFrom;
    const src = selectedCfg();
    if (!state.league || !src || !fromIso || !toIso) return;
    const veil = $('[data-veil="thinking"]');
    const fromLine = $('[data-veil-line="grid"]');
    if (fromLine) fromLine.textContent = `moving ${shortMonthDay(fromIso)} onto the rain-check grid…`;
    const people = $('[data-veil-line="people"]');
    if (people) people.textContent = "keeping owed games at twelve — this is not a new Saturday…";
    veil.setAttribute("data-veil-engine", "z3");
    show(veil, true);
    await new Promise((r) => setTimeout(r, 60));
    const copy = structuredClone(src);
    const result = applyWashout(state.league, copy.games, fromIso, toIso);
    if (!result.moved || !result.washout) {
      show(veil, false);
      state.washNote = result.diagnostics[0] || "Nothing could move.";
      src.diagnostics = [...new Set([...(src.diagnostics || []), ...result.diagnostics])];
      render();
      return;
    }
    const n = state.configurations.length + 1;
    copy.id = `cfg-${n}`;
    copy.name = `${shortMonthDay(fromIso)} → ${shortMonthDay(toIso)}`;
    copy.createdAt = "just now";
    copy.published = false;
    copy.games = result.games;
    copy.washouts = [...(src.washouts || []), result.washout];
    copy.diagnostics = result.diagnostics;
    restamp(copy);
    copy.scores.push({
      key: "rain-check",
      text: `moved ${shortMonthDay(fromIso)} onto ${shortMonthDay(toIso)} — still ${owedGames(state.league)} games owed`,
    });
    const shared = copy.scores.find((s) => s.key === "shared-coach");
    if (shared && !copy.diagnostics.some((d) => /camel's back/i.test(d))) {
      copy.scores.push({
        key: "rain-coach",
        text: shared.text.replace("kept apart", "kept apart on rain check"),
      });
    }
    state.configurations = [copy, ...state.configurations];
    state.selectedId = copy.id;
    state.washFrom = undefined;
    state.washNote = undefined;
    state.inspect = "schedule";
    show(veil, false);
    render();
    return;
  }
  if (target.getAttribute("data-action") === "publish-config") {
    const cfg = selectedCfg();
    if (!cfg || !state.league) return;
    for (const c of state.configurations) c.published = c.id === cfg.id;
    state.publishedId = cfg.id;
    render();
    return;
  }
  const kind = target.getAttribute("data-doc");
  const cfg = selectedCfg();
  if (!cfg) return;
  const xlsx = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";
  if (kind === "league-schedule") {
    const wb = await leagueScheduleWorkbook(state.league, cfg);
    downloadBlob("VSA-Fall-2026-Schedule.xlsx", await workbookToBuffer(wb), xlsx);
  } else if (kind === "academy-schedule") {
    const wb = await leagueScheduleWorkbook(state.league, cfg, { onlyAssociation: "Van Academy" });
    downloadBlob("VSA-Fall-2026-Academy.xlsx", await workbookToBuffer(wb), xlsx);
  } else if (kind === "family-schedules") {
    const scars = documentScars(state.league, cfg);
    if (documentsHeld(scars) && !state.ownScars) return;
    const zip = await familyZip(state.league, cfg);
    downloadBlob("VSA-Fall-2026-Families.zip", zip, "application/zip");
  } else if (kind === "player-schedules") {
    const zip = await playerZip(state.league, cfg);
    downloadBlob("VSA-Fall-2026-Players.zip", zip, "application/zip");
  } else if (kind === "referee-assignments") {
    const wb = await refereeWorkbook(state.league, cfg);
    downloadBlob("VSA-Fall-2026-Referees.xlsx", await workbookToBuffer(wb), xlsx);
  }
});

$('[data-panel="inspect-cards"]').addEventListener("change", (e) => {
  const box = (e.target as HTMLElement).closest('[data-field="own-scars"]') as HTMLInputElement | null;
  if (box) {
    state.ownScars = box.checked;
    render();
    return;
  }
  const jack = (e.target as HTMLElement).closest("[data-jack]") as HTMLSelectElement | null;
  if (!jack || !state.league) return;
  const cfg = selectedCfg();
  if (!cfg) return;
  const id = jack.getAttribute("data-game-id");
  const game = cfg.games.find((g) => g.id === id);
  if (!game) return;
  const kind = jack.getAttribute("data-jack");
  if (kind === "opponent") {
    game.away = jack.value;
  } else if (kind === "kickoff") {
    const kick = parseClock(jack.value);
    if (kick != null) {
      const len = Math.max(40, (parseClock(game.end) || kick + 50) - (parseClock(game.kickoff) || kick));
      game.kickoff = jack.value;
      game.warmupStart = formatClockShort(kick - 15);
      game.end = formatClockShort(kick + len);
      game.vacate = formatClockShort(kick + len + 10);
    }
  }
  restamp(cfg);
  render();
});

async function importWorkbook(file: File) {
  const ribbon = $('[data-progress="import"]');
  ribbon.textContent = "Reading sheets…";
  show(ribbon, true);
  await new Promise((r) => setTimeout(r, 40));
  ribbon.textContent = "Building the season file…";
  const buf = await file.arrayBuffer();
  const result = await parseWorkbook(buf, file.name);
  show(ribbon, false);
  if (!result.ok) {
    showRefusal(result.issues.map((i) => i.message).join("\n"));
    render();
    return;
  }
  hideRefusal();
  const next = result.league!;
  if (result.issues.some((i) => i.code === "unreadable-date")) {
    next.season.dateFlags = result.issues
      .filter((i) => i.code === "unreadable-date")
      .map((i) => ({ raw: i.message, message: i.message }));
  }
  if (state.configurations.length && state.constraintKey) {
    const reason = staleReason(state.constraintKey, next);
    if (!reason) {
      state.refreshLine = "Workbook refreshed — phones and spellings updated; placements kept.";
      for (const c of state.configurations) {
        stampSeasonScores(next, c);
        applySimsJudgment(next, c);
      }
    } else {
      const names = state.configurations.map((c) => c.name.replace(/ —.*/, "")).join(" and ");
      state.refreshLine = `${names} were solved before this refusal. Recalculate.`;
      for (const c of state.configurations) {
        c.stale = `STALE — ${reason}`;
        c.published = false;
      }
      state.publishedId = undefined;
    }
  } else {
    state.configurations = [];
    state.selectedId = undefined;
    state.refreshLine = undefined;
  }
  state.league = next;
  state.constraintKey = constraintKey(next);
  render();
}

function showRefusal(body: string) {
  const card = $('[data-refusal="import"]');
  const title = $("[data-refusal-title]");
  const p = $("[data-refusal-body]");
  if (/not the Van Season workbook/i.test(body) && !/Age groups/i.test(body)) {
    title.textContent = "This is not the Van Season workbook. Download the sample and copy your data into those colored sheets.";
    p.textContent = body;
  } else if (/missing shapes|Age groups, Fields/i.test(body)) {
    title.textContent = "This is not the Van Season workbook.";
    p.textContent = "Age groups, Fields, Campuses, Associations, Families, Staff, Teams, Season";
  } else if (/Z3|SharedArrayBuffer|cross-origin isolated|initZ3/i.test(body)) {
    title.textContent = "Z3 could not calculate this season.";
    p.textContent = body;
    p.setAttribute("data-z3-error", "true");
  } else {
    title.textContent = "The workbook could not become a season.";
    p.textContent = body;
  }
  show(card, true);
}

function hideRefusal() {
  show($('[data-refusal="import"]'), false);
}

function currentDemo(): SimsDemo | null {
  const league = state.league;
  const cfg = selectedCfg();
  if (!league || !cfg) return null;
  const date = firstSaturday(cfg);
  if (!date) return null;
  return playSaturday(league, cfg, date);
}

function pickTraces(demo: SimsDemo): SimsTrace[] {
  const fail = demo.score.traces.filter((t) => t.verdict !== "makes-it");
  if (fail.length) return fail;
  const families = demo.score.traces.filter((t) => t.kind === "family" && t.verdict === "makes-it");
  const named = families.filter((t) => /Hale|Diaz/i.test(t.subject));
  return (named.length ? named : families).slice(0, 3);
}

function paintProof(host: HTMLElement, demo: SimsDemo) {
  const score = demo.score;
  const traces = pickTraces(demo);
  host.setAttribute("data-sims-feasible", score.feasible ? "yes" : "no");
  host.setAttribute("data-sims-valid", score.legal ? "yes" : "no");
  host.setAttribute("data-sims-score", String(score.score));
  const legalLine = score.legal ? "the grid is legal" : "the grid is not legal";
  host.innerHTML = `
    <h3>Saturday proof — ${formatLong(demo.dateIso)}</h3>
    <p class="meta">Every car, every whistle, every kid. The best plan is the verdict — not the solver's word alone.</p>
    <div class="demo-score ${score.feasible ? "ok" : "rust"}" data-sims-banner="${score.feasible ? "holds" : "fails"}">
      <p data-sims-verdict>${score.feasible ? "Saturday holds" : "This Saturday does not hold"} · score ${score.score}</p>
      <p class="meta" data-sims-counts data-sims-legal="${score.legal ? "yes" : "no"}">${legalLine} · two places ${score.twoPlaces} · referee flights ${score.refFlights} · cars short ${score.carsShort}</p>
      ${score.scars.map((s) => `<p class="flag" data-scar="${s.kind}">${s.text}</p>`).join("")}
    </div>
    <div class="proof-traces" data-sims-traces>
      ${traces
        .map(
          (t) => `<article class="proof-trace" data-trace="${t.id}" data-trace-verdict="${t.verdict}" data-trace-subject="${t.subject}">
        <p data-trace-headline>${t.headline}</p>
        <ol data-trace-steps>${t.steps.map((s) => `<li data-trace-step>${s}</li>`).join("")}</ol>
      </article>`,
        )
        .join("")}
    </div>
  `;
}

function restamp(cfg: NonNullable<typeof state.configurations>[number]) {
  if (!state.league) return;
  stampSeasonScores(state.league, cfg);
  applySimsJudgment(state.league, cfg);
}

const VEIL_DEFAULT = {
  grid: "placing games on the 15-minute grid…",
  people: "keeping coaches and parents in one place at a time…",
};

function startThinkingVeil(league: League): () => void {
  const veil = $('[data-veil="thinking"]');
  const grid = $('[data-veil-line="grid"]');
  const people = $('[data-veil-line="people"]');
  const cramp = $('[data-veil-line="cramp"]');
  const scratcher = isScratcherLeague(league);
  veil.setAttribute("data-veil-engine", "z3");
  veil.setAttribute("data-veil-corpus", scratcher ? "scratcher" : "sample");
  const beats = scratcher
    ? [
        ["packing 300 kids onto eight pitches…", "eight referees, one 10U field — every Saturday counts…", "16U has no local opponent; guests must travel…"],
        ["placing games on the 15-minute grid…", "keeping parent-coaches in one place at a time…", "Mineola, Forney, Lindale take the 16U Saturdays…"],
        ["warm-up and vacate on the same grass…", "one car, two brackets, one campus when we can…", "Z3 is packing the whole fall, not a single week…"],
      ]
    : [
        ["placing games on the 15-minute grid…", "keeping coaches and parents in one place at a time…", ""],
        ["preferred 6U slots first, then 8U…", "folding easy sides so the SAT heap stays small…", ""],
      ];
  let i = 0;
  const paint = () => {
    const b = beats[i % beats.length];
    if (grid) grid.textContent = b[0];
    if (people) people.textContent = b[1];
    if (cramp) {
      cramp.textContent = b[2] || "";
      cramp.hidden = !b[2];
    }
    i += 1;
  };
  paint();
  show(veil, true);
  const t = window.setInterval(paint, 2200);
  return () => {
    window.clearInterval(t);
    show(veil, false);
    if (grid) grid.textContent = VEIL_DEFAULT.grid;
    if (people) people.textContent = VEIL_DEFAULT.people;
    if (cramp) {
      cramp.textContent = "";
      cramp.hidden = true;
    }
    veil.removeAttribute("data-veil-corpus");
  };
}

function scoreLine(cfg: Configuration, key: string): string {
  return cfg.scores.find((s) => s.key === key)?.text || "";
}

function bracketOpponents(league: League, game: { home: string; away: string; ageGroup: string }): string[] {
  const pool = league.teams.filter((t) => t.bracket === game.ageGroup).map((t) => teamLabel(t));
  const others = pool.filter((n) => n !== game.home);
  if (!others.includes(game.away)) others.unshift(game.away);
  return others;
}

function kickoffChoices(league: League, game: { ageGroup: string; kickoff: string }): string[] {
  const slots = league.preferredSlots.filter((p) => norm(p.bracket) === norm(game.ageGroup)).map((p) => p.time);
  const out = [...new Set([game.kickoff, ...slots])];
  return out;
}

function diversityMatrixHtml(league: League, cfg: Configuration): string {
  const brackets = [...new Set(cfg.games.map((g) => g.ageGroup))].sort();
  return brackets
    .map((bracket) => {
      const teams = league.teams.filter((t) => t.bracket === bracket).map((t) => teamLabel(t));
      if (teams.length < 2) return "";
      const counts = new Map<string, number>();
      for (const g of cfg.games) {
        if (g.ageGroup !== bracket) continue;
        const k = [g.home, g.away].sort().join("|");
        counts.set(k, (counts.get(k) || 0) + 1);
      }
      return `<div class="matrix-wrap" data-diversity-matrix="${bracket}">
        <p class="meta">${bracket} who-played-whom</p>
        <table><thead><tr><th></th>${teams.map((t) => `<th>${t.replace(bracket + " ", "")}</th>`).join("")}</tr></thead>
        <tbody>${teams
          .map((row) => {
            const cells = teams
              .map((col) => {
                if (row === col) return `<td data-cell="self">—</td>`;
                const n = counts.get([row, col].sort().join("|")) || 0;
                return `<td data-pair="${row}|${col}" data-meetings="${n}">${n || "·"}</td>`;
              })
              .join("");
            return `<tr data-matrix-row="${row}"><th>${row.replace(bracket + " ", "")}</th>${cells}</tr>`;
          })
          .join("")}</tbody></table>
      </div>`;
    })
    .join("");
}

function superViewHtml(league: League, cfg: Configuration): string {
  const z3 = cfg.z3Season;
  const div = cfg.diversity;
  const z3Text = scoreLine(cfg, "z3") || z3?.text || "Z3 season: —";
  const divText = scoreLine(cfg, "diversity") || div?.text || "Diversity: —";
  const simsText = scoreLine(cfg, "sims") || "Sims judge: —";
  const washedFrom = (cfg.washouts || []).map((w) => w.fromIso);
  const byWeek = new Map<string, typeof cfg.games>();
  for (const g of cfg.games) {
    byWeek.set(g.dateIso, [...(byWeek.get(g.dateIso) || []), g]);
  }
  const weekKeys = [...byWeek.keys()].sort();
  const burns = seasonBurnLines(league, cfg);
  const fiat = whoFillsFiat(league, cfg.games);
  const allWeeks = [...new Set([...weekKeys, ...washedFrom, ...rainCheckIsos(league)])].sort();
  const rains = rainCheckIsos(league);
  const playDates = (cfg.games.length ? [...new Set(cfg.games.map((g) => g.dateIso))] : []).filter(
    (d) => !rains.includes(d),
  );
  const orderBr = ["6U", "8U", "10U", "10U Girls", "12U", "14U", "14U Girls", "16U"];
  const brackets = [...new Set(cfg.games.map((g) => g.ageGroup))].sort(
    (a, b) => (orderBr.indexOf(a) < 0 ? 99 : orderBr.indexOf(a)) - (orderBr.indexOf(b) < 0 ? 99 : orderBr.indexOf(b)) || a.localeCompare(b),
  );
  const activeSheet =
    (state.sheetBracket && brackets.includes(state.sheetBracket) ? state.sheetBracket : brackets[0]) || "6U";
  const activeWeek = weekForBracket(cfg.games, activeSheet, state.sheetWeek);
  const weekStrip = `<button type="button" class="chip" data-sheet-week="all" aria-current="${activeWeek ? "false" : "true"}">Season</button>${allWeeks
    .map((d, i) => {
      const w = (cfg.washouts || []).find((x) => x.fromIso === d);
      const live = (cfg.washouts || []).some((x) => x.toIso === d);
      const canWash = playDates.includes(d) && !w;
      const extra = w ? ` data-washed="${d}"` : live ? ` data-rain-live="true"` : "";
      return `<span class="week-chip" data-week="${d}" data-week-index="${i + 1}"${extra}>
        <button type="button" class="chip" data-sheet-week="${d}" aria-current="${activeWeek === d ? "true" : "false"}">${formatSheetDate(d)}</button>
        ${canWash ? `<button type="button" class="link wash-mini" data-action="wash-out" data-week="${d}">wash</button>` : ""}
        ${w ? `<span class="meta">${washCaption(w)}</span>` : ""}
      </span>`;
    })
    .join("")}`;
  const washPicker = state.washFrom
    ? `<article class="card" data-wash-picker="${state.washFrom}">
        <h4>Move these games to which rain check?</h4>
        ${rains
          .map(
            (d) =>
              `<button type="button" class="link" data-action="rain-choice" data-rain-choice="${d}">${formatLong(d)}</button>`,
          )
          .join(" ")}
        ${state.washNote ? `<p class="flag" data-wash-note>${state.washNote}</p>` : ""}
      </article>`
    : `<div data-wash-bar>
        ${
          byeIsos(league).size
            ? `<p class="meta" data-bye-wash="no">Bye — no games to move.</p>`
            : ""
        }
        ${state.washNote ? `<p class="flag" data-wash-note>${state.washNote}</p>` : ""}
      </div>`;
  const focusN = cfg.games.filter((g) => g.ageGroup === activeSheet && (!activeWeek || g.dateIso === activeWeek)).length;
  const focusLine = activeWeek
    ? `<p class="sheet-focus" data-sheet-focus="${activeWeek}">${formatLong(activeWeek)} · ${activeSheet} · ${focusN} games</p>`
    : `<p class="sheet-focus" data-sheet-focus="season">Whole season · ${activeSheet} · ${focusN} games</p>`;
  const bracketBits = (z3?.brackets || []).map((b) => `<p data-z3-bracket="${b.bracket}">${b.text}</p>`).join("");
  return `<article class="card sheet-card" data-card="schedule" data-super-view="season" data-engine="${cfg.engine || ""}" data-z3-verdict="${cfg.z3Verdict || ""}" data-z3-probe="${cfg.z3Probe || ""}" data-sheet-bracket="${activeSheet}" data-sheet-week="${activeWeek || "all"}">
    <div class="triad" data-triad="judges">
      <p data-score="z3" title="${z3Text.replace(/"/g, "")}" data-z3-cost="${z3?.cost ?? ""}" data-z3-score="${z3?.score ?? ""}">${z3Text}</p>
      <p data-score="diversity" title="${divText.replace(/"/g, "")}" data-diversity-score="${div?.score ?? ""}">${divText}</p>
      <p data-score="sims" title="${simsText.replace(/"/g, "")}">${simsText}</p>
    </div>
    <div class="ramification ${state.ramificationKind || ""}" data-ramification="${state.ramification ? "yes" : "no"}" data-ramification-kind="${state.ramificationKind || ""}">${
      state.ramification || `<p class="meta">Grab a row. Drop it on another game in this bracket. They swap kickoff and grass — Z3, diversity, and Sims re-score the whole season immediately.</p>`
    }${state.swapUndo ? `<p><button type="button" class="link" data-action="undo-swap">Undo this swap</button></p>` : ""}</div>
    <div data-z3-brackets class="quiet-brackets">${bracketBits}</div>
    <nav data-week-strip class="week-strip">${weekStrip}</nav>
    ${washPicker}
    ${focusLine}
    <nav class="sheet-tabs" data-sheet-tabs>${brackets
      .map((b) => {
        const awayN = cfg.games.filter((g) => g.ageGroup === b && isAwayCampus(publishedLocation(league, g.campus))).length;
        return `<button type="button" class="chip" data-sheet-tab="${b}" data-tab-away="${awayN}" aria-current="${b === activeSheet ? "true" : "false"}">${b}${awayN ? ` · ${awayN} away` : ""}</button>`;
      })
      .join("")}</nav>
    <div class="sheet-stage" data-sheet-host data-sheet-bracket="${activeSheet}" data-sheet-week="${activeWeek || "all"}"></div>
    <div data-sims-burns class="burns-line">
      ${burns.length ? `<p class="flag" data-burn>${burns[0]}</p>` : `<p class="meta" data-burn="none">no burns — every household and whistle holds</p>`}
    </div>
    <div data-fiat="who-fills">
      <h4>Fiat windows — who fills best</h4>
      ${
        fiat.length
          ? fiat
              .map(
                (f) =>
                  `<p data-fiat-window="${f.dateIso || f.window}" data-fiat-best="${f.best}">${f.why}</p>`,
              )
              .join("")
          : `<p class="meta">No external windows on this sitting.</p>`
      }
    </div>
    <details data-diversity-board>
      <summary>Diversity matrix</summary>
      ${diversityMatrixHtml(league, cfg)}
    </details>
  </article>`;
}

