function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function rosterBand(ag: AgeGroup): { min: number; max: number } {
  const lo = ag.minOnField ?? 3;
  const hi = Math.max(ag.maxOnField ?? lo, lo);
  if (ag.name === "6U" || ag.name === "8U") return { min: lo, max: 12 };
  if (ag.name === "10U") return { min: hi, max: 16 };
  if (ag.name === "12U") return { min: hi, max: 18 };
  return { min: hi, max: 22 };
}

function field(name: string, type: string, campus: string, parking: string, availableRaw: string): Field {
  return { name, type, campus, parking, availableRaw, windows: parseAvailability(availableRaw) };
}

export interface ScratcherFacts {
  kids: number;
  families: number;
  refs: number;
  teamsByBracket: Record<string, number>;
  fieldsByType: Record<string, number>;
  awayLeagues: string[];
  parentCoachFamilyShare: number;
  multiBracketCoachFamilyShare: number;
  teamsWithoutAssistant: number;
  rosterSpread: boolean;
}

export function scratcherFacts(league: League): ScratcherFacts {
  const van = (t: Team) => league.associations.find((a) => a.name === t.association)?.controlled;
  const kids = league.teams.filter(van).reduce((n, t) => n + t.players.length, 0);
  const teamsByBracket: Record<string, number> = {};
  for (const t of league.teams.filter(van)) {
    teamsByBracket[t.bracket] = (teamsByBracket[t.bracket] || 0) + 1;
  }
  const fieldsByType: Record<string, number> = {};
  for (const f of league.fields.filter((f) => /van/i.test(f.campus))) {
    fieldsByType[f.type] = (fieldsByType[f.type] || 0) + 1;
  }
  const coachBrackets = new Map<string, Set<string>>();
  for (const t of league.teams) {
    if (!t.coach) continue;
    const key = printName(t.coach).toLowerCase();
    const set = coachBrackets.get(key) || new Set<string>();
    set.add(t.bracket);
    coachBrackets.set(key, set);
  }
  const parentCoach = league.families.filter((f) => f.parents.some((p) => p.coachOf.length > 0));
  const multi = league.families.filter((f) =>
    f.children.some((c) => {
      const team = league.teams.find((t) => t.name === c.team && t.bracket === c.bracket);
      if (!team?.coach) return false;
      return (coachBrackets.get(printName(team.coach).toLowerCase())?.size || 0) >= 2;
    }),
  );
  const rosterSpread = league.teams.filter(van).every((t) => {
    const ag = league.ageGroups.find((a) => a.name === t.bracket);
    if (!ag) return false;
    const band = rosterBand(ag);
    return t.players.length >= band.min && t.players.length <= band.max;
  });
  return {
    kids,
    families: league.families.length,
    refs: league.staff.length,
    teamsByBracket,
    fieldsByType,
    awayLeagues: league.associations.filter((a) => !a.controlled).map((a) => a.name),
    parentCoachFamilyShare: parentCoach.length / Math.max(1, league.families.length),
    multiBracketCoachFamilyShare: multi.length / Math.max(1, league.families.length),
    teamsWithoutAssistant: league.teams.filter(van).filter((t) => !t.assistant).length,
    rosterSpread,
  };
}

export function buildHeadScratcherLeague(seed = SCRATCHER_DEFAULTS.seed): League {
  const rand = mulberry32(seed);
  const spec = SCRATCHER_DEFAULTS;
  const ageGroups = NTSSA_AGE_GROUPS.filter((a) => spec.teams[a.name]).map((a) => ({
    ...a,
    fieldClasses: [...a.fieldClasses],
    mayPlayWith: [...a.mayPlayWith],
  }));

  let phoneN = 2000;
  const nextPhone = () => `903-555-${String(phoneN++).padStart(4, "0")}`;
  const used = new Set<string>();
  let nameIx = 0;
  const uniq = (first: string, last: string) => {
    let f = first;
    let n = 0;
    while (used.has(`${f} ${last}`.toLowerCase())) f = `${first}${++n}`;
    used.add(`${f} ${last}`.toLowerCase());
    return { first: f, last };
  };
  const nextFirst = () => FIRSTS[nameIx++ % FIRSTS.length];

  const vanTeams: Team[] = [];
  for (const [bracket, count] of Object.entries(spec.teams)) {
    const ag = ageGroups.find((a) => a.name === bracket)!;
    const band = rosterBand(ag);
    const names = TEAM_NAMES[bracket] || [];
    for (let i = 0; i < count; i++) {
      const span = band.max - band.min + 1;
      const size = band.min + ((i + Math.floor(rand() * 3)) % span);
      vanTeams.push({
        name: names[i] || `Side ${i + 1}`,
        bracket,
        association: "Van Rec",
        jersey: JERSEYS[i % JERSEYS.length],
        players: Array.from({ length: size }, () => ({ name: "" })),
        willNotPlay: [],
        willNotTravelTo: bracket === "10U" && i === 0 ? ["Forney Complex"] : [],
        awayDesired: bracket === "16U" ? 8 : bracket === "10U" ? 3 : 0,
        guestDesired: bracket === "16U" ? 4 : bracket === "12U" ? 2 : 0,
        guestTravel: bracket === "16U" ? "we travel" : undefined,
      });
    }
  }

  const kidCount = () => vanTeams.reduce((n, t) => n + t.players.length, 0);
  let bump = 0;
  while (kidCount() < spec.kidsMin && bump < 500) {
    const t = vanTeams[bump++ % vanTeams.length];
    const band = rosterBand(ageGroups.find((a) => a.name === t.bracket)!);
    if (t.players.length < band.max) t.players.push({ name: "" });
  }

  type Open = { team: Team; index: number };
  const open: Open[] = [];
  for (const team of vanTeams) team.players.forEach((_, index) => open.push({ team, index }));
  const take = (team: Team): Open | undefined => {
    const i = open.findIndex((s) => s.team === team);
    if (i < 0) return undefined;
    return open.splice(i, 1)[0];
  };
  const writeKid = (slot: Open, first: string, last: string) => {
    const kid = uniq(first, last);
    slot.team.players[slot.index] = { name: `${kid.first} ${kid.last}` };
    return kid;
  };

  const families: Family[] = [];
  const six = vanTeams.filter((t) => t.bracket === "6U");
  const eight = vanTeams.filter((t) => t.bracket === "8U");
  const ten = vanTeams.filter((t) => t.bracket === "10U");
  const twelve = vanTeams.filter((t) => t.bracket === "12U");
  const sixteen = vanTeams.filter((t) => t.bracket === "16U");

  const duals: Team[][] = [];
  const dualPairs = Math.min(4, six.length, eight.length);
  for (let i = 0; i < dualPairs; i++) duals.push([six[i], eight[i]]);
  if (twelve[0] && sixteen[0]) duals.push([twelve[0], sixteen[0]]);
  if (twelve[1] && ten[0]) duals.push([twelve[1], ten[0]]);

  const covered = new Set<Team>();
  const coachFam = new Map<Team, Family>();
  let lastIx = 0;

  const addFamily = (opts: {
    last: string;
    headTeams: Team[];
    assistantTeam?: Team;
    extraKids?: number;
  }) => {
    const last = LASTS[lastIx++ % LASTS.length];
    const head = uniq(nextFirst(), last);
    const mate = uniq(nextFirst(), last);
    const kids: Family["children"] = [];
    const coachOf: string[] = [];
    const assistantOf: string[] = [];
    const headPhone = nextPhone();
    const matePhone = nextPhone();

    for (const team of opts.headTeams) {
      covered.add(team);
      team.coach = { first: head.first, last: head.last, phone: headPhone };
      coachOf.push(teamLabel(team));
      const slot = take(team);
      if (slot) {
        const kid = writeKid(slot, nextFirst(), last);
        kids.push({ first: kid.first, last: kid.last, bracket: team.bracket, team: team.name });
      }
      const sib = take(team);
      if (sib) {
        const kid = writeKid(sib, nextFirst(), last);
        kids.push({ first: kid.first, last: kid.last, bracket: team.bracket, team: team.name });
      }
    }

    if (opts.assistantTeam && !opts.assistantTeam.assistant) {
      opts.assistantTeam.assistant = { first: mate.first, last: mate.last, phone: matePhone };
      assistantOf.push(teamLabel(opts.assistantTeam));
      const slot = take(opts.assistantTeam);
      if (slot) {
        const kid = writeKid(slot, nextFirst(), last);
        kids.push({
          first: kid.first,
          last: kid.last,
          bracket: opts.assistantTeam.bracket,
          team: opts.assistantTeam.name,
        });
      }
    }

    const extras = opts.extraKids ?? 1;
    for (let e = 0; e < extras; e++) {
      const team = opts.headTeams[e % opts.headTeams.length];
      const slot = take(team);
      if (!slot) continue;
      const kid = writeKid(slot, nextFirst(), last);
      kids.push({ first: kid.first, last: kid.last, bracket: team.bracket, team: team.name });
    }

    const parents: Parent[] = [
      { first: head.first, last: head.last, phone: headPhone, coachOf, assistantOf: [] },
    ];
    if (assistantOf.length) {
      parents.push({ first: mate.first, last: mate.last, phone: matePhone, coachOf: [], assistantOf });
    } else {
      parents.push({ first: mate.first, last: mate.last, phone: matePhone, coachOf: [], assistantOf: [] });
    }
    families.push({ parents, children: kids });
    const fam = families[families.length - 1];
    for (const team of opts.headTeams) coachFam.set(team, fam);
  };

  for (let i = 0; i < duals.length; i++) {
    const pair = duals[i];
    const assistantTeam =
      i % 3 === 0
        ? undefined
        : i % 2 === 0
          ? pair.find((t) => t.bracket === "8U")
          : ten[i % Math.max(1, ten.length)];
    addFamily({ last: LASTS[i], headTeams: pair, assistantTeam, extraKids: 2 });
  }

  for (const team of vanTeams) {
    if (covered.has(team)) continue;
    addFamily({ last: LASTS[lastIx], headTeams: [team], extraKids: 2 });
  }

  const noAssistant = new Set<Team>([...six.filter((_, i) => i % 2 === 0), ...ten.slice(-1), ...sixteen]);
  for (const team of vanTeams) {
    if (noAssistant.has(team)) team.assistant = undefined;
  }

  const dualTeams = new Set(
    vanTeams.filter((t) => {
      if (!t.coach) return false;
      const who = printName(t.coach);
      return vanTeams.filter((x) => x.coach && printName(x.coach) === who).length >= 2;
    }),
  );
  const byTeamOpen = new Map<Team, Open[]>();
  for (const slot of open) {
    const list = byTeamOpen.get(slot.team) || [];
    list.push(slot);
    byTeamOpen.set(slot.team, list);
  }
  open.length = 0;

  const absorb = (fam: Family, team: Team, slots: Open[]) => {
    const last = fam.parents[0]?.last || "Guest";
    for (const slot of slots) {
      const kid = writeKid(slot, nextFirst(), last);
      fam.children.push({ first: kid.first, last: kid.last, bracket: team.bracket, team: team.name });
    }
  };

  for (const team of vanTeams) {
    const slots = byTeamOpen.get(team) || [];
    if (!slots.length) continue;
    if (dualTeams.has(team)) {
      const last = LASTS[lastIx++ % LASTS.length];
      const p1 = uniq(nextFirst(), last);
      const p2 = uniq(nextFirst(), last);
      const kids: Family["children"] = [];
      for (const slot of slots) {
        const kid = writeKid(slot, nextFirst(), last);
        kids.push({ first: kid.first, last: kid.last, bracket: team.bracket, team: team.name });
      }
      families.push({
        parents: [
          { first: p1.first, last: p1.last, phone: nextPhone(), coachOf: [], assistantOf: [] },
          { first: p2.first, last: p2.last, phone: nextPhone(), coachOf: [], assistantOf: [] },
        ],
        children: kids,
      });
      continue;
    }
    const fam = coachFam.get(team);
    if (fam) absorb(fam, team, slots);
  }

  const leftoverEmpty = vanTeams.flatMap((t) => t.players.filter((p) => !p.name));
  if (leftoverEmpty.length) {
    throw new Error(`unnamed players: ${leftoverEmpty.length}`);
  }

  const fields: Field[] = [];
  const smallLetters = ["A", "B", "C", "D", "E", "F"];
  for (let i = 0; i < spec.smallFields; i++) {
    const lot = i < 2 ? "Lot North" : i < 4 ? "Lot East" : "Lot South";
    fields.push(
      field(
        `Van Complex Field ${smallLetters[i]}`,
        "small",
        "Van Complex",
        lot,
        i === 0 ? "Saturday 8:00–18:00" : "Saturday 8:00–18:00; Monday 18:00–20:30",
      ),
    );
  }
  fields.push(field("Van Complex Field G", "medium", "Van Complex", "Lot East", "Saturday 8:00–18:00"));
  fields.push(field("Van Complex Field H", "nine", "Van Complex", "Lot South", "Saturday 8:00–18:00"));
  fields.push(field("Van High School Stadium", "full", "Van High School", "Student Lot", "Saturday 12:00–18:00"));
  for (const a of AWAYS) {
    fields.push(field(`${a.name} 7v7`, "medium", a.campus, "Visitor lot", "Saturday 8:00–18:00"));
    fields.push(field(`${a.name} 9v9`, "nine", a.campus, "Visitor lot", "Saturday 8:00–18:00"));
    fields.push(field(`${a.name} 11v11`, "full", a.campus, "Visitor lot", "Saturday 8:00–18:00"));
  }

  const refNames = ["Quinn Adler", "Priya Shah", "Jordan Vale", "Sam Brooks", "Riley Cruz", "Casey Dunn", "Morgan Ellis", "Jamie Ford"];
  const staff = refNames.map((full, i) => {
    const [first, last] = full.split(" ");
    const all = ageGroups.map((a) => a.name);
    const centerOf = i < 2 ? all : i < 5 ? all.filter((n) => n !== "16U") : ["6U", "8U"];
    const assistantOf = i < 3 ? ["10U", "12U", "16U"] : i < 6 ? ["10U"] : [];
    return {
      first,
      last,
      phone: nextPhone(),
      centerOf,
      assistantOf,
      vacation: i === 7 ? "August 22" : undefined,
    };
  });

  const campuses = [
    { name: "Van Complex", association: "Van Rec", street: "445 S Oak St, Van, TX 75790", lat: 32.5243, lng: -95.6374 },
    { name: "Van High School", association: "Van Rec", street: "4666 FM 16 W, Van, TX 75790", lat: 32.5258, lng: -95.6411 },
    ...AWAYS.map((a) => ({ name: a.campus, association: a.name, street: a.street, lat: a.lat, lng: a.lng })),
  ];

  const associations = [
    { name: "Van Rec", controlled: true, homeCampus: "Van Complex", guestSides: [] as League["associations"][0]["guestSides"] },
    ...AWAYS.map((a) => ({
      name: a.name,
      controlled: false,
      homeCampus: a.campus,
      guestSides: [
        { ageGroup: "16U", teamCount: 2, gamesRequested: 4, name: `${a.name} 16U`, jersey: "navy" },
        { ageGroup: "10U", teamCount: 2, gamesRequested: 3, name: `${a.name} 10U`, jersey: "white" },
        { ageGroup: "12U", teamCount: 1, gamesRequested: 2, name: `${a.name} 12U`, jersey: "red" },
      ],
    })),
  ];

  const travel = [
    { from: "Van Complex", to: "Van High School", minutes: 8 },
    ...AWAYS.map((a) => ({ from: "Van Complex", to: a.campus, minutes: a.minutes })),
    { from: "Mineola Complex", to: "Forney Complex", minutes: 40 },
    { from: "Mineola Complex", to: "Lindale Complex", minutes: 18 },
    { from: "Forney Complex", to: "Lindale Complex", minutes: 55 },
  ];

  const league: League = {
    ageGroups,
    fieldTypes: NTSSA_FIELD_TYPES.map((t) => ({ ...t })),
    fields,
    campuses,
    associations,
    travel,
    families,
    staff,
    teams: vanTeams,
    season: {
      associationName: "Van Soccer Association",
      title: "Fall 2026 to 2027 — head-scratcher",
      headerTitle: "Fall 2026–2027",
      weekStarts: "Saturday",
      firstRaw: "Saturday, August 22",
      lastRaw: "Saturday, November 14",
      firstIso: "2026-08-22",
      lastIso: "2026-11-14",
      rematchCap: 2,
      specials: [
        { kind: "bye", raw: "Thanksgiving week — no games", note: "Thanksgiving week — no games", iso: "2026-11-14" },
        { kind: "rain-check", raw: "Saturday, November 21", iso: "2026-11-21" },
        { kind: "interleague-home", raw: "Saturday, September 20", iso: "2026-09-20", note: "guests come to Van Complex" },
        { kind: "interleague-away", raw: "Saturday, September 27", iso: "2026-09-27", note: "Van may travel" },
        { kind: "interleague-away", raw: "Saturday, October 18", iso: "2026-10-18", note: "Van may travel" },
      ],
      dateFlags: [],
    },
    preferredSlots: [
      { bracket: "6U", rank: 1, day: "Saturday", time: "8:30" },
      { bracket: "8U", rank: 1, day: "Saturday", time: "9:15" },
      { bracket: "10U", rank: 1, day: "Saturday", time: "10:00", venue: "Van Complex Field G" },
      { bracket: "12U", rank: 1, day: "Saturday", time: "10:00", venue: "Van Complex Field H" },
      { bracket: "16U", rank: 1, day: "Saturday", time: "1:00", venue: "Van High School Stadium" },
    ],
    carveOuts: [],
    sourceName: "VSA-Head-Scratcher.xlsx",
    sampleOnly: false,
  };
  league.travel = fillCrowFlies(league);
  return league;
}
